package rails

import "time"

// ConnInfo identifies the WebSocket connection an observation came from. ConnID is generated by
// the SDK and stays the same across the reconnects of one logical connection.
type ConnInfo struct {
	ConnID  string
	Market  string
	Attempt int
}

// ConnectStats breaks a successful dial into its phases. A phase the transport skipped is zero.
type ConnectStats struct {
	DNS     time.Duration
	TCP     time.Duration
	TLS     time.Duration
	Upgrade time.Duration
	Total   time.Duration
}

// DisconnectReason says why a connection ended.
type DisconnectReason string

const (
	// ReasonServerShutdown covers both the connectionShutdown notice and the 1012 close.
	ReasonServerShutdown DisconnectReason = "serverShutdown"
	ReasonCloseFrame     DisconnectReason = "closeFrame"
	ReasonMissedPong     DisconnectReason = "missedPong"
	ReasonReadError      DisconnectReason = "readError"
	ReasonWriteError     DisconnectReason = "writeError"
)

// ReqInfo identifies a command sent over a WebSocket connection.
type ReqInfo struct {
	ConnID          string
	Op              string
	Market          string
	ClientRequestID string
}

// HTTPInfo identifies an HTTP call. StatusCode is zero when the call never got a response.
type HTTPInfo struct {
	Op         string
	Method     string
	URL        string
	StatusCode int
	Attempt    int
}

// Hooks receives every measurement the SDK takes, so the same numbers are available to you and
// to Rails. Set the funcs you want and leave the rest nil; a field added in a later release
// changes nothing for existing callers.
//
// A func runs on the goroutine that made the observation and must not block: do the work on
// your own goroutine, and never call back into the SDK from a hook.
type Hooks struct {
	// ConnectStarted fires before every dial, reconnects included.
	ConnectStarted func(ConnInfo)
	// ConnectFinished reports how the dial went: its phases, and the error when it failed.
	ConnectFinished func(ConnInfo, ConnectStats, error)
	// Disconnected fires when a socket is lost, before the reconnect that follows. Closing the
	// connection yourself does not fire it.
	Disconnected func(ConnInfo, DisconnectReason)
	// PingRTT is the round trip of each keepalive ping.
	PingRTT func(ConnInfo, time.Duration)
	// RequestAcked reports send → 202.
	RequestAcked func(ReqInfo, time.Duration)
	// RequestDone reports send → terminal frame, or the failure that replaced it.
	RequestDone func(ReqInfo, time.Duration, error)
	// HTTPDone reports every HTTP attempt, retries included, with its status or its error.
	HTTPDone func(HTTPInfo, time.Duration, error)
	// Paced reports a call the pacer delayed or refused. Only fires with [WithPacer].
	Paced func(PaceInfo)
	// Throttled reports the exchange rate-limiting a call; the pacer holds the class back for
	// retryAfter. Only fires with [WithPacer].
	Throttled func(class OpClass, retryAfter time.Duration)
}
